// @ts-nocheck

// Runtime helper: converts a CSS property string to a React style object.
// Used where Framer generates inline style="…" attributes.
function css(str: string): React.CSSProperties {
  const obj: Record<string, string> = {};
  str.split(';').forEach((decl) => {
    const col = decl.indexOf(':');
    if (col === -1) return;
    const prop = decl.substring(0, col).trim();
    const value = decl.substring(col + 1).trim();
    if (!prop || !value) return;
    if (prop.startsWith('--')) {
      (obj as Record<string, string>)[prop] = value;
    } else {
      const camel = prop.replace(/-([a-z])/g, (_: string, c: string) => c.toUpperCase());
      obj[camel] = value;
    }
  });
  return obj as React.CSSProperties;
}

